import{_ as c,r as i,o as l,c as d,e as r,b as t,d as s,a,w as o}from"./app-84ed3530.js";const u={},k={href:"https://docs.astral.sh/uv/",target:"_blank",rel:"noopener noreferrer"},m={href:"https://fastapi.tiangolo.com/",target:"_blank",rel:"noopener noreferrer"},h={href:"https://docs.sqlalchemy.org/",target:"_blank",rel:"noopener noreferrer"};function b(v,n){const e=i("RouterLink"),p=i("ExternalLinkIcon");return l(),d("div",null,[n[14]||(n[14]=r(`<h1 id="python-后端开发指南" tabindex="-1"><a class="header-anchor" href="#python-后端开发指南" aria-hidden="true">#</a> Python 后端开发指南</h1><blockquote><p>Python 是 AI 时代的事实标准胶水语言：既能写服务端（FastAPI/Django），又是模型与 Agent 生态（Pydantic、LangChain 等）的第一载体。本文面向有 JS/Go 经验的工程师，按「环境 → 语言 → 框架 → 数据 → AI 生态」主线整理。</p></blockquote><hr><h2 id="_1-环境与工程化-先把这个理顺" tabindex="-1"><a class="header-anchor" href="#_1-环境与工程化-先把这个理顺" aria-hidden="true">#</a> 1. 环境与工程化（先把这个理顺）</h2><p>Python 的「环境地狱」是新手劝退第一关，2024 年后标准答案已收敛到 <strong>uv</strong>：</p><table><thead><tr><th>工具</th><th>定位</th><th>现状</th></tr></thead><tbody><tr><td><strong>uv</strong></td><td>Rust 编写的一体化工具：包管理 + 虚拟环境 + Python 版本管理 + 锁文件</td><td>事实上的新一代标准，极快</td></tr><tr><td>venv + pip</td><td>标准库内置</td><td>仍在广泛使用，理解它有助于理解一切</td></tr><tr><td>poetry</td><td>依赖管理老牌方案</td><td>存量大，新项目多被 uv 替代</td></tr><tr><td>pyenv</td><td>多 Python 版本</td><td>uv 已内置该能力</td></tr></tbody></table><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># uv 典型工作流</span>
uv init my-app <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">cd</span> my-app
uv <span class="token function">add</span> fastapi uvicorn        <span class="token comment"># 加依赖（自动建 venv + 写锁文件）</span>
uv run python main.py         <span class="token comment"># 在项目环境里执行</span>
uv python <span class="token function">install</span> <span class="token number">3.13</span>        <span class="token comment"># 管理解释器版本</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>版本现状（2026）</strong>：3.13（2024.10）引入实验性 free-threaded 构建（去除 GIL，PEP 703）与实验性 JIT；3.14（2025.10）起 free-threading 进入官方支持阶段。生产选型写服务建议 3.12/3.13，做 AI 生态跟随框架要求即可。</p><hr><h2 id="_2-语言核心-从-js-go-视角快速建立正确的认知" tabindex="-1"><a class="header-anchor" href="#_2-语言核心-从-js-go-视角快速建立正确的认知" aria-hidden="true">#</a> 2. 语言核心：从 JS/Go 视角快速建立正确的认知</h2><h3 id="_2-1-必须吃透的六个点" tabindex="-1"><a class="header-anchor" href="#_2-1-必须吃透的六个点" aria-hidden="true">#</a> 2.1 必须吃透的六个点</h3><ol><li><strong>动态强类型 + 类型注解</strong>：注解（<code>def f(x: int) -&gt; str</code>）运行时不强制，但配合 <strong>mypy / pyright</strong> 做静态检查后，工程体验接近 TS。现代项目（尤其 FastAPI）默认全量注解</li><li><strong>GIL（全局解释器锁）</strong>：CPython 中同一时刻只有一个线程执行 Python 字节码。因此 <strong>CPU 密集用 multiprocessing/进程池，IO 密集用 asyncio 或线程</strong>；3.13+ 的 free-threading 构建可摆脱 GIL，但生态兼容仍在推进</li><li><strong>一切皆对象</strong>：函数是一等公民，装饰器（<code>@decorator</code>）就是「接收函数返回函数」的语法糖——理解了它就读懂了 FastAPI/Django 的大部分魔法</li><li><strong>鸭子类型 + 魔法方法</strong>：<code>__len__</code>、<code>__enter__/__exit__</code>（with 语句）、<code>__iter__</code> 等协议决定对象行为；类型注解时代用 <code>Protocol</code>（结构化类型，类似 TS 的 interface）表达鸭子类型</li><li><strong>asyncio</strong>：<code>async def / await</code> 与 JS 的 async/await 心智一致；区别是 Python 有独立的事件循环（<code>asyncio.run()</code>），CPU 密集任务用 <code>asyncio.to_thread()</code> 抛给线程</li><li><strong>包管理与导入</strong>：模块 = 文件，包 = 带 <code>__init__.py</code> 的目录；相对导入 <code>. / ..</code>，命名空间与 JS 的 ESM 有差异，踩坑高发</li></ol><h3 id="_2-2-数据结构速查" tabindex="-1"><a class="header-anchor" href="#_2-2-数据结构速查" aria-hidden="true">#</a> 2.2 数据结构速查</h3><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token comment"># 列表推导式（最常用的 Pythonic 写法）</span>
squares <span class="token operator">=</span> <span class="token punctuation">[</span>x <span class="token operator">*</span> x <span class="token keyword">for</span> x <span class="token keyword">in</span> <span class="token builtin">range</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span> <span class="token keyword">if</span> x <span class="token operator">%</span> <span class="token number">2</span> <span class="token operator">==</span> <span class="token number">0</span><span class="token punctuation">]</span>
<span class="token comment"># 字典 / 集合推导</span>
heights <span class="token operator">=</span> <span class="token punctuation">{</span>u<span class="token punctuation">.</span>name<span class="token punctuation">:</span> u<span class="token punctuation">.</span>height <span class="token keyword">for</span> u <span class="token keyword">in</span> users<span class="token punctuation">}</span>
<span class="token comment"># 解构与打包</span>
first<span class="token punctuation">,</span> <span class="token operator">*</span>rest <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">]</span>
<span class="token comment"># 生成器：惰性求值，处理大数据不爆内存</span>
total <span class="token operator">=</span> <span class="token builtin">sum</span><span class="token punctuation">(</span><span class="token builtin">len</span><span class="token punctuation">(</span>line<span class="token punctuation">)</span> <span class="token keyword">for</span> line <span class="token keyword">in</span> <span class="token builtin">open</span><span class="token punctuation">(</span><span class="token string">&quot;big.log&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span>
<span class="token comment"># dataclass：结构化数据容器（Pydantic 的「标准库版」）</span>
<span class="token keyword">from</span> dataclasses <span class="token keyword">import</span> dataclass

<span class="token decorator annotation punctuation">@dataclass</span>
<span class="token keyword">class</span> <span class="token class-name">User</span><span class="token punctuation">:</span>
    name<span class="token punctuation">:</span> <span class="token builtin">str</span>
    age<span class="token punctuation">:</span> <span class="token builtin">int</span> <span class="token operator">=</span> <span class="token number">0</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="_3-web-框架-fastapi-与-django-怎么选" tabindex="-1"><a class="header-anchor" href="#_3-web-框架-fastapi-与-django-怎么选" aria-hidden="true">#</a> 3. Web 框架：FastAPI 与 Django 怎么选</h2><table><thead><tr><th></th><th><strong>FastAPI</strong></th><th><strong>Django</strong></th><th><strong>Flask</strong></th></tr></thead><tbody><tr><td>定位</td><td>现代 API 服务（ASGI）</td><td>全家桶（ORM/Admin/Auth/迁移）</td><td>微框架，自己组装</td></tr><tr><td>类型与校验</td><td>Pydantic + 注解，自动 OpenAPI 文档</td><td>表单/序列化器体系</td><td>手动或插件</td></tr><tr><td>异步</td><td>原生 async</td><td>3.x 起逐步支持（ORM 异步接口）</td><td>需搭配 ASGI（如 Quart）</td></tr><tr><td>适合</td><td>API 服务、AI 服务、微服务</td><td>内容型/管理后台型全栈应用</td><td>小服务、原型</td></tr></tbody></table><h3 id="_3-1-fastapi-最小可用示例-生产骨架" tabindex="-1"><a class="header-anchor" href="#_3-1-fastapi-最小可用示例-生产骨架" aria-hidden="true">#</a> 3.1 FastAPI 最小可用示例（生产骨架）</h3><div class="language-python line-numbers-mode" data-ext="py"><pre class="language-python"><code><span class="token keyword">from</span> fastapi <span class="token keyword">import</span> FastAPI<span class="token punctuation">,</span> HTTPException<span class="token punctuation">,</span> Depends
<span class="token keyword">from</span> pydantic <span class="token keyword">import</span> BaseModel<span class="token punctuation">,</span> Field

app <span class="token operator">=</span> FastAPI<span class="token punctuation">(</span>title<span class="token operator">=</span><span class="token string">&quot;demo&quot;</span><span class="token punctuation">)</span>
items<span class="token punctuation">:</span> <span class="token builtin">dict</span><span class="token punctuation">[</span><span class="token builtin">int</span><span class="token punctuation">,</span> <span class="token builtin">dict</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>          <span class="token comment"># 演示用内存存储</span>

<span class="token keyword">class</span> <span class="token class-name">ItemIn</span><span class="token punctuation">(</span>BaseModel<span class="token punctuation">)</span><span class="token punctuation">:</span>
    name<span class="token punctuation">:</span> <span class="token builtin">str</span> <span class="token operator">=</span> Field<span class="token punctuation">(</span>min_length<span class="token operator">=</span><span class="token number">1</span><span class="token punctuation">,</span> max_length<span class="token operator">=</span><span class="token number">50</span><span class="token punctuation">)</span>
    price<span class="token punctuation">:</span> <span class="token builtin">float</span> <span class="token operator">=</span> Field<span class="token punctuation">(</span>gt<span class="token operator">=</span><span class="token number">0</span><span class="token punctuation">)</span>

<span class="token decorator annotation punctuation">@app<span class="token punctuation">.</span>get</span><span class="token punctuation">(</span><span class="token string">&quot;/items/{item_id}&quot;</span><span class="token punctuation">)</span>
<span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">get_item</span><span class="token punctuation">(</span>item_id<span class="token punctuation">:</span> <span class="token builtin">int</span><span class="token punctuation">)</span><span class="token punctuation">:</span>          <span class="token comment"># 路径参数自动类型转换与校验</span>
    <span class="token keyword">if</span> item_id <span class="token keyword">not</span> <span class="token keyword">in</span> items<span class="token punctuation">:</span>
        <span class="token keyword">raise</span> HTTPException<span class="token punctuation">(</span>status_code<span class="token operator">=</span><span class="token number">404</span><span class="token punctuation">,</span> detail<span class="token operator">=</span><span class="token string">&quot;not found&quot;</span><span class="token punctuation">)</span>
    <span class="token keyword">return</span> items<span class="token punctuation">[</span>item_id<span class="token punctuation">]</span>

<span class="token decorator annotation punctuation">@app<span class="token punctuation">.</span>post</span><span class="token punctuation">(</span><span class="token string">&quot;/items&quot;</span><span class="token punctuation">,</span> status_code<span class="token operator">=</span><span class="token number">201</span><span class="token punctuation">)</span>
<span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">create_item</span><span class="token punctuation">(</span>item<span class="token punctuation">:</span> ItemIn<span class="token punctuation">)</span><span class="token punctuation">:</span>       <span class="token comment"># 请求体自动解析 + 校验</span>
    new_id <span class="token operator">=</span> <span class="token builtin">len</span><span class="token punctuation">(</span>items<span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token number">1</span>
    items<span class="token punctuation">[</span>new_id<span class="token punctuation">]</span> <span class="token operator">=</span> item<span class="token punctuation">.</span>model_dump<span class="token punctuation">(</span><span class="token punctuation">)</span>      <span class="token comment"># model_dump 是 Pydantic v2 API</span>
    <span class="token keyword">return</span> <span class="token punctuation">{</span><span class="token string">&quot;id&quot;</span><span class="token punctuation">:</span> new_id<span class="token punctuation">,</span> <span class="token operator">**</span>items<span class="token punctuation">[</span>new_id<span class="token punctuation">]</span><span class="token punctuation">}</span>

<span class="token comment"># 依赖注入：鉴权、DB 会话等横切关注点的标准位置</span>
<span class="token keyword">async</span> <span class="token keyword">def</span> <span class="token function">current_user</span><span class="token punctuation">(</span>token<span class="token punctuation">:</span> <span class="token builtin">str</span> <span class="token operator">=</span> Depends<span class="token punctuation">(</span>parse_token<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">-</span><span class="token operator">&gt;</span> User<span class="token punctuation">:</span>
    <span class="token punctuation">.</span><span class="token punctuation">.</span><span class="token punctuation">.</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>要点：<strong>Pydantic 模型即文档</strong>（自动生成 <code>/docs</code> 的 OpenAPI/Swagger）；<code>Depends</code> 是 Nest.js 式依赖注入的 Python 版；部署用 <code>uvicorn</code>（单 worker 异步）或 <code>gunicorn -k uvicorn.workers.UvicornWorker</code> 多进程。</p><h3 id="_3-2-django-一句话定位" tabindex="-1"><a class="header-anchor" href="#_3-2-django-一句话定位" aria-hidden="true">#</a> 3.2 Django 一句话定位</h3><p>ORM + Admin 后台 + 认证体系开箱即用，DRF（Django REST framework）做 API。适合「有管理后台、以 CRUD 为主体」的业务系统；学习成本高于 FastAPI 但体系完整。</p><hr><h2 id="_4-数据访问与任务队列" tabindex="-1"><a class="header-anchor" href="#_4-数据访问与任务队列" aria-hidden="true">#</a> 4. 数据访问与任务队列</h2><table><thead><tr><th>场景</th><th>主流方案</th><th>说明</th></tr></thead><tbody><tr><td>ORM</td><td><strong>SQLAlchemy 2.0</strong></td><td>事实标准；2.0 起原生支持 async（<code>AsyncSession</code>）</td></tr><tr><td>迁移</td><td>Alembic</td><td>配 SQLAlchemy 做版本化迁移</td></tr><tr><td>FastAPI 生态 ORM</td><td>SQLModel / Tortoise</td><td>SQLModel 由 FastAPI 作者维护，Pydantic + SQLAlchemy 合体</td></tr><tr><td>后台任务</td><td><strong>Celery</strong> / arq / dramatiq</td><td>Celery 最成熟（配 Redis/RabbitMQ 作 broker）；async 栈可选 arq</td></tr><tr><td>缓存</td><td>redis-py</td><td>客户端自带异步版本</td></tr><tr><td>测试</td><td><strong>pytest</strong></td><td>fixture 体系 + 参数化是精髓，配 <code>pytest-asyncio</code> 测异步</td></tr></tbody></table><hr><h2 id="_5-python-在-ai-工程里的位置-呼应本站-ai-主题" tabindex="-1"><a class="header-anchor" href="#_5-python-在-ai-工程里的位置-呼应本站-ai-主题" aria-hidden="true">#</a> 5. Python 在 AI 工程里的位置（呼应本站 AI 主题）</h2><ul><li><strong>Pydantic</strong> 是整个 LLM 应用生态的地基：结构化输出、Agent 参数校验、配置管理都在用它</li><li>模型侧：PyTorch / transformers / vLLM 全是 Python 生态；推理服务常用 FastAPI 包一层</li><li>Agent 侧：LangChain / LlamaIndex / pydantic-ai 等框架均为 Python 优先</li><li>因此「全栈 AI Agent 工程师」的合理配置是：<strong>TypeScript 做产品与前端，Python 做 AI 服务与数据处理</strong>，两者经 HTTP/队列协作</li></ul><hr><h2 id="_6-工程规范清单" tabindex="-1"><a class="header-anchor" href="#_6-工程规范清单" aria-hidden="true">#</a> 6. 工程规范清单</h2><ul><li><input type="checkbox" class="task-checkbox" disabled> 格式化与 lint 统一到 <strong>ruff</strong>（一个工具替代 black/isort/flake8，快 10-100x）</li><li><input type="checkbox" class="task-checkbox" disabled> 类型检查：pyright（快）或 mypy（插件多），CI 强制</li><li><input type="checkbox" class="task-checkbox" disabled> 不用 <code>requirements.txt</code> 裸奔：锁文件（<code>uv.lock</code> / <code>poetry.lock</code>）进版本库</li><li><input type="checkbox" class="task-checkbox" disabled> 密钥走环境变量（pydantic-settings），绝不进代码</li><li><input type="checkbox" class="task-checkbox" disabled> 异步服务里不要混用阻塞调用（<code>requests</code> 换 <code>httpx</code>），否则卡死整个事件循环</li><li><input type="checkbox" class="task-checkbox" disabled> 测试金字塔：pytest 单测 + FastAPI <code>TestClient</code> 集成测</li></ul><hr><h2 id="_7-延伸阅读" tabindex="-1"><a class="header-anchor" href="#_7-延伸阅读" aria-hidden="true">#</a> 7. 延伸阅读</h2>`,33)),t("ul",null,[t("li",null,[n[4]||(n[4]=s("站内：",-1)),a(e,{to:"/blogs/backend/language-selection.html"},{default:o(()=>[...n[0]||(n[0]=[s("后端语言选型对比",-1)])]),_:1}),n[5]||(n[5]=s(" · ",-1)),a(e,{to:"/blogs/backend/docker.html"},{default:o(()=>[...n[1]||(n[1]=[s("Docker 指南",-1)])]),_:1}),n[6]||(n[6]=s(" · ",-1)),a(e,{to:"/blogs/backend/mysql.html"},{default:o(()=>[...n[2]||(n[2]=[s("MySQL",-1)])]),_:1}),n[7]||(n[7]=s(" · ",-1)),a(e,{to:"/blogs/backend/redis.html"},{default:o(()=>[...n[3]||(n[3]=[s("Redis",-1)])]),_:1})]),t("li",null,[n[11]||(n[11]=s("官方：",-1)),t("a",k,[n[8]||(n[8]=s("uv",-1)),a(p)]),n[12]||(n[12]=s(" · ",-1)),t("a",m,[n[9]||(n[9]=s("FastAPI",-1)),a(p)]),n[13]||(n[13]=s(" · ",-1)),t("a",h,[n[10]||(n[10]=s("SQLAlchemy 2.0",-1)),a(p)])])])])}const g=c(u,[["render",b],["__file","python.html.vue"]]);export{g as default};
